class EvalFinder(ast.NodeVisitor):
    def visit_Call(self, node):
        if isinstance(node.func, ast.Name) and node.func.id == "eval":
            print(f"line {node.lineno}: eval() is forbidden")
        self.generic_visit(node)

EvalFinder().visit(ast.parse(open("app.py").read()))

class TimeoutChecker(BaseChecker):
    name = "timeout"
    msgs = {"W9001": ("requests call without timeout", "requests-no-timeout", "Always pass timeout=")}
    def visit_call(self, node):
        if node.func.as_string().startswith("requests.") and not any(k.arg == "timeout" for k in node.keywords or []):
            self.add_message("requests-no-timeout", node=node)

def register(linter): linter.register_checker(TimeoutChecker(linter))

class ShellTrue(ast.NodeVisitor):
    def __init__(self): self.alias = {}
    def visit_Import(self, n):
        for a in n.names: self.alias[a.asname or a.name] = a.name
    def visit_Call(self, n):
        f = n.func
        if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) and self.alias.get(f.value.id) == "subprocess":
            if any(k.arg == "shell" and getattr(k.value, "value", False) is True for k in n.keywords):
                print(f"line {n.lineno}: subprocess with shell=True")
        self.generic_visit(n)
